// Track Taka service worker — full offline app shell.
//
// Hand-written on purpose: the app is a static prerender with all data in
// IndexedDB (RxDB), so there is no API to sync — only pages and assets to
// cache. Install precaches the WHOLE app so it works offline on first
// launch, without the person having to visit every page first:
//
//   1. Every route from public/sw-precache.json (generated by
//      scripts/generate-sw-precache.mjs at build time) is stored twice:
//      as an HTML document (hard loads, start_url) and as a soft-navigation
//      RSC payload (<route>?_rsc with the RSC header — what the Next router
//      actually requests when a <Link> is tapped).
//   2. Every /_next/static asset reachable from those files is crawled and
//      cached — HTML gives the initial scripts/CSS/fonts, and parsing each
//      JS chunk for further "static/chunks/…" references picks up chunks
//      only reachable through dynamic imports (recharts, html-to-image, …).
//
// Runtime strategies on top of the precache:
//
//   navigations            network-first  → shell cache → /offline.html
//   /_next/static/**       cache-first    (content-hashed, immutable)
//   RSC payloads           network-first  → runtime cache (client-side
//   (?_rsc, RSC: 1)                         navigation works offline)
//   other same-origin GET  network-first  → runtime cache (images, screenshots)
//   non-GET / cross-origin never intercepted
//
// Deploys reach already-installed apps without a VERSION bump: the registrar
// sends REFRESH_PRECACHE on page load and the worker re-runs the whole
// precache when sw-precache.json's buildId differs from the cached marker.
// Bump VERSION only when the strategies or cache layout change.

const VERSION = "v2"
const SHELL_CACHE = `track-taka-shell-${VERSION}`
const STATIC_CACHE = `track-taka-static-${VERSION}`
const RUNTIME_CACHE = `track-taka-runtime-${VERSION}`
const KNOWN_CACHES = [SHELL_CACHE, STATIC_CACHE, RUNTIME_CACHE]

/** Routes cached even without a precache manifest (dev, stale deploys). */
const FALLBACK_PAGES = ["/", "/dashboard"]

/** Public assets every install needs: the offline fallback, the manifest,
 * and the icons (splash screen + Apple touch icon work offline too). */
const PUBLIC_PRECACHE = [
  "/offline.html",
  "/manifest.webmanifest",
  "/icon.svg",
  "/favicon.ico",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-maskable-512.png",
  "/icons/apple-touch-icon.png",
]

const PRECACHE_MANIFEST_URL = "/sw-precache.json"
/** Synthetic key in SHELL_CACHE holding the buildId the precache came from. */
const PRECACHE_MARKER = "/__precache-build__"
const CRAWL_CONCURRENCY = 6

const STATIC_LIMIT = 600
const RUNTIME_LIMIT = 240
/** Move on to the cached shell if the network is this slow (ms). */
const NAV_TIMEOUT = 7500

let precacheInFlight = null

self.addEventListener("install", (event) => {
  event.waitUntil(runPrecache())
})

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Fetch the navigation in parallel while the worker starts up.
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload
          .enable()
          .catch(() => undefined)
      }
      const names = await caches.keys()
      await Promise.all(
        names
          .filter(
            (name) =>
              name.startsWith("track-taka-") && !KNOWN_CACHES.includes(name)
          )
          .map((name) => caches.delete(name))
      )
      await self.clients.claim()
    })()
  )
})

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting()
  if (event.data?.type === "REFRESH_PRECACHE")
    event.waitUntil(refreshPrecache())
})

self.addEventListener("fetch", (event) => {
  const { request } = event
  if (request.method !== "GET") return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(event))
    return
  }

  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, STATIC_CACHE, STATIC_LIMIT))
    return
  }

  // Full RSC payloads carry RSC: 1 without a prefetch marker; prefetch and
  // segment-prefetch responses are partial and must not be stored where a
  // real navigation could pick them up.
  const isPrefetch = request.headers.get("Next-Router-Prefetch") === "1"
  const isSegmentPrefetch = request.headers.has("Next-Router-Segment-Prefetch")
  const isRscNavigation =
    request.headers.get("RSC") === "1" && !isPrefetch && !isSegmentPrefetch
  if (isRscNavigation) {
    event.respondWith(networkFirst(request, RUNTIME_CACHE, RUNTIME_LIMIT))
    return
  }

  if (!isPrefetch && !isSegmentPrefetch && !url.searchParams.has("_rsc")) {
    event.respondWith(networkFirst(request, RUNTIME_CACHE, RUNTIME_LIMIT))
  }
})

// ---------------------------------------------------------------------------
// Precache
// ---------------------------------------------------------------------------

/** Precache everything once; concurrent callers (install + REFRESH_PRECACHE
 * from two tabs) share the same run. */
function runPrecache() {
  precacheInFlight ??= precacheEverything().finally(() => {
    precacheInFlight = null
  })
  return precacheInFlight
}

async function precacheEverything() {
  const shell = await caches.open(SHELL_CACHE)
  await Promise.all(PUBLIC_PRECACHE.map((url) => precacheFile(shell, url)))

  const manifest = await readPrecacheManifest()
  const pages = manifest?.pages ?? FALLBACK_PAGES
  const assetSeeds = new Set()
  let cachedPages = 0

  await Promise.all(
    pages.map(async (page) => {
      const seeds = await precachePage(page)
      if (seeds) {
        cachedPages += 1
        for (const url of seeds) assetSeeds.add(url)
      }
    })
  )

  // A silent total failure would activate a worker that can only serve
  // /offline.html. Failing the install makes the browser retry it on the
  // next navigation instead. (The current app keeps serving from the old
  // worker until then.)
  if (manifest && cachedPages === 0)
    throw new Error("precache: no pages could be fetched")

  await Promise.all([
    shell.put(PRECACHE_MARKER, new Response(manifest?.buildId ?? "unknown")),
    crawlAssets([...assetSeeds]),
  ])
}

/** Cache one route as HTML + RSC payload. Returns the build-asset URLs
 * referenced by the two, or null when neither could be fetched. */
async function precachePage(page) {
  const [html, rsc] = await Promise.all([
    fetchTextInto(SHELL_CACHE, page),
    // The router requests soft-navigation payloads at <route>?_rsc; the
    // bare RSC header alone answers with a 307 to that exact URL.
    fetchTextInto(RUNTIME_CACHE, `${page}?_rsc`, { headers: { RSC: "1" } }),
  ])
  if (!html && !rsc) return null

  const seeds = new Set()
  for (const text of [html, rsc]) {
    if (!text) continue
    for (const url of extractAssetUrls(text)) seeds.add(url)
  }
  return [...seeds]
}

/** Fetch with the HTTP cache bypassed, store, and return the response text
 * so callers can mine it for more asset URLs. Null on any failure. */
async function fetchTextInto(cacheName, url, init) {
  try {
    const request = new Request(url, init)
    const response = await fetch(request, { cache: "reload" })
    if (!response.ok || response.type !== "basic") return null
    const text = await response.clone().text()
    const cache = await caches.open(cacheName)
    await cache.put(request, response)
    return text
  } catch {
    return null
  }
}

async function precacheFile(cache, url) {
  try {
    const response = await fetch(url, { cache: "reload" })
    if (response.ok && response.type === "basic") await cache.put(url, response)
  } catch {
    // One missing public asset must not fail the whole install.
  }
}

/** Breadth-first walk of the build-asset graph: cache each asset, and parse
 * JS/CSS for further references (dynamic imports, fonts) until the set of
 * known URLs stops growing. */
async function crawlAssets(seeds) {
  const queue = seeds
  const seen = new Set(seeds)

  const worker = async () => {
    let url = queue.shift()
    while (url) {
      try {
        const response = await fetch(url, { cache: "reload" })
        if (response.ok && response.type === "basic") {
          const type = response.headers.get("Content-Type") ?? ""
          const parseable = /javascript|css/.test(type)
          const text = parseable ? await response.clone().text() : null
          await putCached(
            STATIC_CACHE,
            new Request(url),
            response,
            STATIC_LIMIT
          )
          if (text) {
            for (const next of extractAssetUrls(text)) {
              if (!seen.has(next)) {
                seen.add(next)
                queue.push(next)
              }
            }
          }
        }
      } catch {
        // One bad asset must not stop the crawl.
      }
      url = queue.shift()
    }
  }

  await Promise.all(Array.from({ length: CRAWL_CONCURRENCY }, worker))
}

/** Pull every build-hashed asset reference out of HTML, RSC payloads, JS
 * and CSS. Turbopack emits three shapes:
 *   "/_next/static/chunks/x.js"     HTML attributes, RSC flight data, CSS
 *   "static/chunks/x.js"            the chunk-loading map inside the runtime
 *   url(../media/x.woff2)           fonts referenced relatively from CSS */
function extractAssetUrls(text) {
  const urls = new Set()
  for (const match of text.matchAll(/\/_next\/static\/[a-zA-Z0-9._/-]+/g))
    urls.add(match[0])
  for (const match of text.matchAll(
    /["']static\/(chunks|media)\/[a-zA-Z0-9._/-]+["']/g
  )) {
    urls.add(`/_next/${match[0].slice(1, -1)}`)
  }
  for (const match of text.matchAll(
    /\.\.\/(chunks|media)\/[a-zA-Z0-9._/-]+/g
  )) {
    // A CSS file lives at /_next/static/chunks/a.css, so ../media/x resolves
    // to /_next/static/media/x — strip the "../", never concatenate it.
    urls.add(`/_next/static/${match[0].slice(3)}`)
  }
  return [...urls]
}

async function readPrecacheManifest() {
  try {
    const response = await fetch(PRECACHE_MANIFEST_URL, { cache: "reload" })
    if (!response.ok) return null
    const manifest = await response.json()
    return Array.isArray(manifest?.pages) && manifest.pages.length > 0
      ? manifest
      : null
  } catch {
    return null
  }
}

/** Called on every controlled page load (online): re-run the precache when
 * the running build differs from the one already cached, so a deploy lands
 * in installed apps on their next visit — no VERSION bump needed. */
async function refreshPrecache() {
  const manifest = await readPrecacheManifest()
  if (!manifest) return

  const shell = await caches.open(SHELL_CACHE)
  const marker = await shell.match(PRECACHE_MARKER)
  if ((await marker?.text()) === manifest.buildId) return

  await runPrecache()
}

// ---------------------------------------------------------------------------
// Fetch strategies
// ---------------------------------------------------------------------------

/** Pages: fresh when online, the last-seen copy when offline, a branded
 * fallback when the page was never cached. */
async function handleNavigation(event) {
  const { request } = event
  try {
    const preloaded = await event.preloadResponse
    const response = await raceTimeout(preloaded || fetch(request), NAV_TIMEOUT)
    if (response.ok && response.type === "basic") {
      putCached(SHELL_CACHE, request, response.clone())
    }
    return response
  } catch {
    const cache = await caches.open(SHELL_CACHE)
    return (
      (await matchIn(cache, request)) ||
      (await matchIn(cache, stripSearch(request))) ||
      (await cache.match("/offline.html")) ||
      Response.error()
    )
  }
}

/** Immutable hashed assets: hit the cache, then the network once. */
async function cacheFirst(request, cacheName, limit) {
  const cached = await matchIn(null, request)
  if (cached) return cached
  const response = await fetch(request)
  if (response.ok && response.type === "basic") {
    putCached(cacheName, request, response.clone(), limit)
  }
  return response
}

/** Freshness first, cache as the offline fallback. */
async function networkFirst(request, cacheName, limit) {
  try {
    const response = await raceTimeout(fetch(request), NAV_TIMEOUT)
    if (response.ok && response.type === "basic") {
      putCached(cacheName, request, response.clone(), limit)
    }
    return response
  } catch {
    const hit = await matchIn(null, request)
    if (hit) return hit

    // A first-ever offline visit to /dashboard?quick=expense&_rsc can reuse
    // the payload cached for /dashboard?_rsc: the flight data for a route
    // does not depend on the query, the page reads it from the URL.
    const url = new URL(request.url)
    if (
      url.searchParams.has("_rsc") &&
      [...url.searchParams.keys()].some((key) => key !== "_rsc")
    ) {
      url.search = "?_rsc"
      return (
        (await matchIn(null, new Request(url, { headers: { RSC: "1" } }))) ||
        Response.error()
      )
    }
    return Response.error()
  }
}

// ---------------------------------------------------------------------------
// Cache helpers
// ---------------------------------------------------------------------------

/** Match ignoring Vary. RSC responses vary on router headers
 * (next-router-state-tree, …) whose values differ per client, so matching
 * by those headers would never hit; a route has exactly one canonical
 * payload per URL, which makes URL-only matching correct. */
async function matchIn(cache, request) {
  try {
    const hit = cache
      ? await cache.match(request, { ignoreVary: true })
      : await caches.match(request, { ignoreVary: true })
    if (hit) return hit
  } catch {
    // Very old browsers without ignoreVary: fall through to exact matching.
  }
  return cache ? cache.match(request) : caches.match(request)
}

/** Fire and forget: store, then keep the cache bounded. */
function putCached(cacheName, request, response, limit) {
  void caches
    .open(cacheName)
    .then((cache) => cache.put(request, response))
    .then(() => trimCache(cacheName, limit))
}

async function trimCache(cacheName, limit) {
  const cache = await caches.open(cacheName)
  const keys = await cache.keys()
  // keys() is in insertion order, so the oldest entries go first.
  await Promise.all(
    keys
      .slice(0, Math.max(0, keys.length - limit))
      .map((key) => cache.delete(key))
  )
}

/** Resolve with the fetch result, or reject after `ms` so the caller can
 * fall back to the cache. The fetch itself keeps running and still fills
 * the cache. */
function raceTimeout(fetchPromise, ms) {
  let fetchResult = fetchPromise
  // preloadResponse and fetch() can reject before anyone awaits the race.
  if (fetchResult && typeof fetchResult.catch === "function") {
    fetchResult = fetchPromise.catch(() => {
      throw new Error("request failed")
    })
  }
  return Promise.race([
    fetchResult,
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error("timeout")), ms)
    ),
  ])
}

function stripSearch(request) {
  const url = new URL(request.url)
  url.search = ""
  return new Request(url, { method: "GET" })
}
